const filters=document.querySelectorAll('[data-filter]');
filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('[data-type]').forEach(drink=>{drink.hidden=button.dataset.filter!=='all'&&drink.dataset.type!==button.dataset.filter;if(!drink.hidden)count++});document.querySelector('#menu-status').textContent=`Showing ${count} imagined drinks${button.dataset.filter==='free'?' · spirit-free':button.dataset.filter==='cocktail'?' · with spirit':''}.`;}));
const form=document.querySelector('#planner'),card=document.querySelector('#evening-card');
form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form);card.replaceChildren();const kicker=document.createElement('p');kicker.className='tiny';kicker.textContent='AFTER HOURS / YOUR EVENING';card.append(kicker);const heading=document.createElement('h3');heading.textContent=data.get('company');card.append(heading);[['THE SOUND',data.get('mood')],['THE FIRST SIP',data.get('drink')]].forEach(([name,value])=>{const line=document.createElement('p');line.className='card-line';const label=document.createElement('small');label.textContent=name;line.append(label,document.createTextNode(value));card.append(line)});const note=document.createElement('p');note.className='footnote';note.textContent='A little inspiration, just for you. This is not a reservation. Nothing has been sent or stored.';card.append(note);const reset=document.createElement('button');reset.type='button';reset.className='reset';reset.textContent='← Try another kind of evening';reset.addEventListener('click',()=>{card.hidden=true;form.hidden=false;form.querySelector('select').focus()});card.append(reset);form.hidden=true;card.hidden=false;card.tabIndex=-1;card.focus();});
